function renderGames(){const gameTabs=`<div class="pill-group"><button class="pill ${selectedGame==='ttt'?'active':''}" data-action="game-select" data-game="ttt">❎ Tic Tac Toe</button><button class="pill ${selectedGame==='snake'?'active':''}" data-action="game-select" data-game="snake">🎲 Snakes & Ladders</button></div>`;
const localHint=note(tr('localGame'));let board='';if(selectedGame==='ttt'){
const status=ttt.winner?(ttt.winner==='draw'?tr('draw'):`${tr('winner')}: ${ttt.winner}`):`${tr('player')} ${ttt.turn} · ${tr('yourTurn')}`;
board=`<section class="card flat"><div class="flex-between wrap"><div class="field" style="min-width:150px;margin:0"><label for="tttMode">${label('gameMode')}</label><select id="tttMode" data-setting="tttmode"><option value="computer" ${ttt.mode==='computer'?'selected':''}>${label('computer')}</option><option value="local" ${ttt.mode==='local'?'selected':''}>${label('twoPlayers')}</option></select></div>${timerSelect(ttt.seconds,'ttttimer')}</div><div class="game-status" id="turnstatus">${esc(status)}</div><div id="gameClock" class="small-text" style="text-align:center"></div><div class="ttt-grid">${ttt.cells.map((v,i)=>`<button class="ttt-cell ${v==='O'?'o':''}" data-action="ttt-move" data-index="${i}" ${v||ttt.winner?'disabled':''} aria-label="Cell ${i+1}">${v||''}</button>`).join('')}</div><div class="flex-between">${btn(label('newGame'),'reset-ttt','primary')}<span class="small-text">Rudra · RUDEL Games</span></div></section>`;
}else{
const snakes={17:7,54:34,62:19,87:36,93:73,95:75,99:78};const ladders={3:22,5:8,11:26,20:29,27:56,36:44,51:67,71:92,80:98};
const squares=Array.from({length:100},(_,i)=>{const row=Math.floor(i/10),pos=i%10;return 100-row*10-(row%2===0?pos:9-pos)});
board=`<section class="card flat"><div class="flex-between wrap"><strong>${snake.win!==null?`${label('winner')}: ${tr('player')} ${snake.win+1}`:`${label('player')} ${snake.turn+1} · ${label('yourTurn')}`}</strong>${timerSelect(snake.seconds,'snaketimer')}</div><p id="gameClock" class="small-text"></p><div class="ladders-board" aria-label="Snakes and ladders board">${squares.map(n=>`<div class="ladder-cell ${snakes[n]?'snake':ladders[n]?'ladder':''}" title="${snakes[n]?`Snake to ${snakes[n]}`:ladders[n]?`Ladder to ${ladders[n]}`:n}">${n}${(snake.pos[0]===n||snake.pos[1]===n)?`<span class="token">${snake.pos[0]===n?'🔵':''}${snake.pos[1]===n?'🟠':''}</span>`:''}</div>`).join('')}</div><div class="flex-between wrap" style="margin-top:16px"><button class="btn primary" data-action="roll-dice" ${snake.win!==null?'disabled':''}>🎲 ${label('rollDice')}</button><span>${snake.last?`🎲 ${snake.last}`:''}</span>${btn(label('newGame'),'reset-snake')}</div><div class="small-text">🔵 ${label('player')} 1: ${snake.pos[0]} · 🟠 ${label('player')} 2: ${snake.pos[1]}</div><div class="small-text">Rudra · RUDEL Games</div></section>`;
}
return `${titleBlock('games')}<p class="lead">Tic Tac Toe + Snakes & Ladders</p>${gameTabs}<div style="height:15px"></div>${board}<div style="height:13px"></div>${localHint}`;}
