function renderCapsules(){return `${titleBlock('capsules')}<div class="card flat"><form data-form="capsule">${formField('capsuleName',tr('memoryTitle'),'','','text',true)}${area('capsuleText',tr('message'),tr('message'))}${formField('capsuleDate',tr('unlockDate'),'','','datetime-local',true)}<button class="btn primary" type="submit">+ ${label('scheduleCapsule')}</button></form></div><p class="small-text">${label('notDelivered')}</p><div class="stack">${state.capsules.length?state.capsules.map(c=>{const unlocked=Date.now()>=c.unlockAt;return `<div class="card flat"><div class="flex-between"><strong>${unlocked?'🎁':'🔒'} ${esc(c.title)}</strong><button class="btn mini danger" data-action="delete-capsule" data-id="${attr(c.id)}">${label('delete')}</button></div><div class="small-text">${ts(c.unlockAt)} · ${unlocked?label('unlocked'):label('locked')}</div>${unlocked?`<p>${esc(c.text)}</p>`:''}</div>`}).join(''):blank('🎁',tr('noItems'))}</div>`;}
function renderSound(){return `${titleBlock('sound')}<div class="card flat"><h3>${label('yourAudio')}</h3><div class="flex wrap"><button class="btn primary" data-action="start-record" id="recordButton">🎙 ${label('record')}</button><button class="btn" data-action="stop-record" id="stopRecord" ${!audioRecorder||audioRecorder.state!=='recording'?'disabled':''}>■ ${label('stop')}</button></div><p class="small-text">${label('permissionNeeded')}</p><div id="audio-list">${blank('🎙',tr('noItems'))}</div></div><div class="section-head"><h2>${label('audio')}</h2></div><div class="card flat"><div class="flex-between wrap"><strong>Original RUDEL Chime</strong><button class="btn mini" data-action="play-chime">▶ ${label('play')}</button></div><p class="small-text">${label('soundOn')} · ${label('quietMode')} · ${label('settings')}</p></div><div style="height:12px"></div>${note(tr('featureLater'))}`;}
function renderNotifications(){const unlocked=state.capsules.filter(c=>c.unlockAt<=Date.now());return `${titleBlock('notifications')}<div class="card flat"><div class="flex-between"><strong>🎁 ${label('capsules')}</strong><span class="badge">${unlocked.length}</span></div>${unlocked.length?unlocked.map(c=>`<div class="list-row"><span>🎉</span><strong>${esc(c.title)}</strong><button class="btn mini" data-action="visit" data-to="capsules">${label('continue')}</button></div>`).join(''):`<p class="small-text">${label('noItems')}</p>`}</div><div style="height:12px"></div>${note(tr('featureLater'))}`;}
function renderSettings(){return `${titleBlock('settings')}<div class="card flat"><h3>🌍 ${label('language')}</h3><p class="small-text">${label('englishDefault')}</p><div class="field"><label for="lang">${label('chooseLanguage')}</label><select id="lang" data-setting="lang">${Object.keys(D.langs).map(l=>`<option value="${l}" ${l===state.lang?'selected':''}>${D.langs[l]}</option>`).join('')}</select></div><h3>🎨 ${label('appearance')}</h3><div class="field"><label for="theme">${label('theme')}</label><select id="theme" data-setting="theme">${['aurora','royal','vibrant','light'].map(v=>`<option value="${v}" ${v===state.theme?'selected':''}>${label(v)}</option>`).join('')}</select></div>${[['reducedMotion','reduceMotion'],['dataSaver','dataSaver'],['quietMode','quietMode'],['sound','audio']].map(([prop,k])=>`<label class="list-row"><input type="checkbox" data-setting="${prop}" ${state[prop]?'checked':''} style="width:20px;height:20px"><span>${label(k)}</span></label>`).join('')}<button class="btn mini" style="margin-top:10px" data-action="speak-ui">🔊 ${label('readAloud')}</button></div><div class="section-head"><h2>${label('privacy')}</h2></div><div class="card flat"><p>🛡️ ${label('privateDefault')}</p><div class="flex wrap">${btn(label('exportData'),'export-data')}${btn(label('clearData'),'clear-data','danger')}</div></div><div style="height:13px"></div>${note(tr('localNotice'))}`;}
function renderSafety(){return `${titleBlock('safety')}<div class="card flat"><h3>🔐 ${label('privacy')}</h3><p>${label('privateDefault')}</p><p>${label('noBackend')}</p><p class="small-text">RUDEL preview stores profile, text, images and preferences in local browser storage. It is not encrypted and is not suitable for confidential information on a shared device. Voice clips are stored in browser IndexedDB. Clearing browser data can remove all content. No automatic cloud sync.</p></div><div class="section-head"><h2>${label('currentStatus')}</h2></div>${note(tr('technicalPreview'))}`;}
