function drawerMarkup(){return `<div class="drawer-backdrop" data-action="close-drawer"><aside class="drawer" data-action="noop" role="dialog" aria-modal="true" aria-label="${label('more')}"><div class="flex-between"><h2>RUDEL · ${label('explore')}</h2><button class="icon-btn" data-action="close-drawer" aria-label="${label('cancel')}">✕</button></div><div class="drawer-grid">${PAGES.filter(n=>!NAV.includes(n)).map(n=>`<button data-action="visit" data-to="${n}">${ICONS[n]} &nbsp; ${label(n)}</button>`).join('')}</div><div style="height:12px"></div>${note(tr('localNotice'))}</aside></div>`;}
function addLocalFriend(name,av){state.friends.unshift({id:uid(),name:name.slice(0,36),avatar:avatars.includes(av)?av:'⭐',date:Date.now()});persist();render();toast(tr('saveOnDevice'));}
function takePicture(file){return new Promise((resolve,reject)=>{if(!file){resolve(null);return;}if(!file.type.startsWith('image/')){reject(new Error('Please select an image.'));return;}if(file.size>12*1024*1024){reject(new Error('Image is too large (12 MB maximum).'));return;}const reader=new FileReader();reader.onerror=()=>reject(new Error('Cannot read photo'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Photo is not supported'));img.onload=()=>{const scale=Math.min(1,820/Math.max(img.width,img.height));const can=document.createElement('canvas');can.width=Math.max(1,Math.round(img.width*scale));can.height=Math.max(1,Math.round(img.height*scale));can.getContext('2d').drawImage(img,0,0,can.width,can.height);let data=can.toDataURL('image/jpeg',.66);if(data.length>550000){can.width=Math.max(1,Math.round(can.width*.65));can.height=Math.max(1,Math.round(can.height*.65));can.getContext('2d').drawImage(img,0,0,can.width,can.height);data=can.toDataURL('image/jpeg',.57);}resolve(data);};img.src=reader.result;};reader.readAsDataURL(file);});}
async function handleForm(e){const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const data=new FormData(form),kind=form.dataset.form;try{
if(kind==='friend'){const name=String(data.get('name')||'').trim();if(!name)return;if(state.friends.length>=40){toast('Local preview limit: 40 friend stars');return;}addLocalFriend(name,String(data.get('avatar')));}
if(kind==='profile'){const name=String(data.get('displayName')||'').trim();if(!name)return;state.name=name.slice(0,40);state.avatar=String(data.get('avatar'));persist();render();toast(tr('profileSaved'));}
if(kind==='post'){const text=String(data.get('postText')||'').trim();const photo=form.querySelector('#postPhoto').files[0]||form.querySelector('#cameraPhoto').files[0];if(!text&&!photo){toast(tr('postText'));return;}if(state.posts.length>=70){toast('Local preview limit: 70 posts');return;}const image=photo?await takePicture(photo):null;state.posts.unshift({id:uid(),text:text.slice(0,2000),image,date:Date.now(),audience:data.get('audience')==='friends'?'friends':'onlyMe',likes:0});state.postDraft='';persist();render();toast(tr('saveOnDevice'));}
if(kind==='circle'){const name=String(data.get('circleName')||'').trim();if(!name)return;state.circles.unshift({id:uid(),name:name.slice(0,50),date:Date.now()});persist();render();toast(tr('saveOnDevice'));}
if(kind==='memory'){const title=String(data.get('memoryTitle')||'').trim();if(!title)return;const text=String(data.get('memoryText')||'').slice(0,2000);const image=form.querySelector('#memoryPhoto').files[0]?await takePicture(form.querySelector('#memoryPhoto').files[0]):null;state.memories.unshift({id:uid(),title:title.slice(0,70),text,image,date:Date.now(),visibility:'onlyMe'});persist();render();toast(tr('saveOnDevice'));}
if(kind==='chat-note'){const text=String(data.get('noteText')||'').trim();if(!text)return;const friend=state.friends.find(f=>f.id===selectedFriend);if(friend){state.drafts[friend.id]=text.slice(0,2000);toast(tr('offlineDraft'));}else{state.notes.unshift({id:uid(),text:text.slice(0,2000),date:Date.now()});toast(tr('saveOnDevice'));}persist();render();}
if(kind==='capsule'){const title=String(data.get('capsuleName')||'').trim(),text=String(data.get('capsuleText')||'').trim(),date=Date.parse(String(data.get('capsuleDate')));if(!title||!text||!Number.isFinite(date)||date<=Date.now()){toast('Select a future date and add a message.');return;}state.capsules.unshift({id:uid(),title:title.slice(0,70),text:text.slice(0,2000),unlockAt:date,date:Date.now()});persist();render();toast(tr('saveOnDevice'));}
}catch(err){console.error(err);toast(err.message||'Could not save this item');}}
function removeFrom(key,id){state[key]=state[key].filter(v=>v.id!==id);persist();render();toast(tr('delete'));}
function toggleIntro(){if(state.introSeen||state.reducedMotion)return;const root=get('overlay');root.innerHTML=`<div class="intro-backdrop" role="dialog" aria-modal="true" aria-label="RUDEL intro"><button class="intro-skip" id="skipIntro">Skip ✕</button><div class="intro-content"><div class="intro-symbol">✦</div><h1>RUDEL</h1><p>Your Friends. Your Stories. Your Universe.</p><div class="meter"><span></span></div></div></div>`;closeIntro=()=>{clearTimeout(introTimer);root.innerHTML='';state.introSeen=true;persist();};get('skipIntro').addEventListener('click',closeIntro);introTimer=setTimeout(closeIntro,4200);}
function tttWinning(cells){for(const [a,b,c] of [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]])if(cells[a]&&cells[a]===cells[b]&&cells[a]===cells[c])return cells[a];return cells.every(Boolean)?'draw':null;}
function minimax(cells,player,depth){const result=tttWinning(cells);if(result)return result==='O'?10-depth:result==='X'?depth-10:0;let best=player==='O'?-Infinity:Infinity;for(let i=0;i<9;i++){if(cells[i])continue;cells[i]=player;const val=minimax(cells,player==='O'?'X':'O',depth+1);cells[i]='';best=player==='O'?Math.max(best,val):Math.min(best,val);}return best;}
function aiTurn(){if(ttt.mode!=='computer'||ttt.turn!=='O'||ttt.winner||selectedGame!=='ttt')return;let best=-Infinity,idx=-1;for(let i=0;i<9;i++){if(ttt.cells[i])continue;ttt.cells[i]='O';const score=minimax(ttt.cells,'X',0);ttt.cells[i]='';if(score>best){best=score;idx=i;}}if(idx>=0){ttt.cells[idx]='O';ttt.winner=tttWinning(ttt.cells);ttt.turn='X';ttt.start=Date.now();render();playOriginalChime(false);}}
function tttMove(index){if(index<0||index>8||ttt.cells[index]||ttt.winner||(ttt.mode==='computer'&&ttt.turn!=='X'))return;ttt.cells[index]=ttt.turn;ttt.winner=tttWinning(ttt.cells);if(!ttt.winner)ttt.turn=ttt.turn==='X'?'O':'X';ttt.start=Date.now();render();playOriginalChime(false);if(!ttt.winner&&ttt.mode==='computer'&&ttt.turn==='O')setTimeout(aiTurn,360);}
function resetTtt(){ttt={cells:Array(9).fill(''),mode:ttt.mode,turn:'X',winner:null,seconds:ttt.seconds,start:Date.now()};render();}
function rand6(){const bits=new Uint32Array(1);try{const limit=4294967296-(4294967296%6);do{crypto.getRandomValues(bits);}while(bits[0]>=limit);return bits[0]%6+1;}catch(e){return Math.floor(Math.random()*6)+1;}}
function rollDice(){if(snake.win!==null)return;const n=rand6();snake.last=n;let p=snake.pos[snake.turn]+n;const snakes={17:7,54:34,62:19,87:36,93:73,95:75,99:78},ladders={3:22,5:8,11:26,20:29,27:56,36:44,51:67,71:92,80:98};if(p<=100){p=snakes[p]||ladders[p]||p;snake.pos[snake.turn]=p;}if(p===100)snake.win=snake.turn;else snake.turn=1-snake.turn;snake.start=Date.now();render();playOriginalChime(false);}
function resetSnake(){snake={pos:[0,0],turn:0,win:null,seconds:snake.seconds,start:Date.now(),last:null};render();}
function tick(){if(page!=='games'||document.hidden)return;const game=selectedGame==='ttt'?ttt:snake;const winner=selectedGame==='ttt'?ttt.winner:snake.win;const remaining=Math.max(0,Math.ceil(game.seconds-(Date.now()-game.start)/1000));const el=get('gameClock');if(el)el.textContent=`⏳ ${remaining}s`;if(winner!==null)return;if(remaining<=0){if(selectedGame==='ttt'){ttt.turn=ttt.turn==='X'?'O':'X';ttt.start=Date.now();toast(tr('skipTurn'));render();if(ttt.mode==='computer'&&ttt.turn==='O')setTimeout(aiTurn,330);}else{snake.turn=1-snake.turn;snake.start=Date.now();toast(tr('skipTurn'));render();}}}
function changeSetting(e){const el=e.target;if(!el.dataset.setting)return;const k=el.dataset.setting;
if(k==='tttmode'){ttt.mode=el.value;resetTtt();return;}
if(k==='ttttimer'){ttt.seconds=Number(el.value);ttt.start=Date.now();render();return;}
if(k==='snaketimer'){snake.seconds=Number(el.value);snake.start=Date.now();render();return;}
if(k==='lang'){if(D.langs[el.value])state.lang=el.value;}
else if(k==='theme'){if(['aurora','royal','vibrant','light'].includes(el.value))state.theme=el.value;}
else if(['reducedMotion','dataSaver','quietMode','sound'].includes(k))state[k]=el.checked;
persist();render();}
function storyChoice(n){const i=state.story.chapter;state.story.choices[i]=n;if(!state.story.clues.includes(i))state.story.clues.push(i);state.story.clues.sort((a,b)=>a-b);if(i===7){const ending=endingIndex();if(!state.story.endings.includes(ending))state.story.endings.push(ending);}persist();render();playOriginalChime(false);}
function setChapter(n){if(n<0||n>=8)return;if(n>state.story.chapter&&state.story.choices[state.story.chapter]===undefined)return;state.story.chapter=n;if(!state.story.clues.includes(n))state.story.clues.push(n);persist();render();}
function speak(text){if(!('speechSynthesis'in window)){toast(tr('noVoice'));return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=langLocale[state.lang];u.rate=0.91;const voices=speechSynthesis.getVoices();const match=voices.find(v=>v.lang.toLowerCase().startsWith(state.lang.toLowerCase()))||voices.find(v=>v.lang.toLowerCase().startsWith(u.lang.toLowerCase().split('-')[0]));if(voices.length&&!match){toast(tr('noVoice'));return;}if(match)u.voice=match;try{speechSynthesis.speak(u);}catch(e){toast(tr('noVoice'));}}
async function cacheOffline(){if(!('serviceWorker'in navigator)||!/^https?:$/.test(location.protocol)){toast('Host RUDEL over HTTPS to install and cache this PWA.');return;}try{const reg=await navigator.serviceWorker.ready;const cache=await caches.open('rudel-v1.0.0');await cache.addAll(['./','./index.html','./data.js','./app.js','./styles.css']);toast(tr('offlineReady'));}catch(e){toast('Offline cache unavailable — check browser storage permissions.');}}
function playOriginalChime(force=true){if(!state.sound||state.quietMode)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=new AC();[440,554.37,659.25].forEach((f,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.0001,ctx.currentTime+i*.105);gain.gain.exponentialRampToValueAtTime(.055,ctx.currentTime+i*.105+.015);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+i*.105+.3);osc.connect(gain).connect(ctx.destination);osc.start(ctx.currentTime+i*.105);osc.stop(ctx.currentTime+i*.105+.31);});setTimeout(()=>ctx.close().catch(()=>{}),1250);}catch(e){if(force)toast('Audio unavailable.');}}
function exportData(){const exportObj={app:'RUDEL',exportedAt:new Date().toISOString(),data:state,notice:'Only on-device text/profile/post/memory metadata; voice clips stored separately in IndexedDB are not included.'};const url=URL.createObjectURL(new Blob([JSON.stringify(exportObj,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='rudel-local-data-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function clearData(){if(!confirm('Delete all RUDEL local profile, posts, memories, games progress and voice clips on this browser? This cannot be undone.'))return;localStorage.removeItem('rudel-v1');if('indexedDB'in window)indexedDB.deleteDatabase('rudel-media-v1');load();render();toast(tr('clearData'));}
function initCanvas(){const c=get('drawingCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);const saved=window.__rudelCanvasImage;if(saved){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,c.width,c.height);img.src=saved;}
const xy=e=>{const b=c.getBoundingClientRect();return{x:(e.clientX-b.left)*c.width/b.width,y:(e.clientY-b.top)*c.height/b.height};};
c.addEventListener('pointerdown',e=>{e.preventDefault();c.setPointerCapture(e.pointerId);drawing=true;canvasUndo.push(c.toDataURL('image/jpeg',.65));if(canvasUndo.length>12)canvasUndo.shift();const p=xy(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.01,p.y+.01);ctx.strokeStyle=canvasColor;ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();});
c.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=xy(e);ctx.lineTo(p.x,p.y);ctx.stroke();});
const end=()=>{if(drawing){drawing=false;window.__rudelCanvasImage=c.toDataURL('image/jpeg',.73);}};c.addEventListener('pointerup',end);c.addEventListener('pointercancel',end);}
function canvasImageAction(action){const c=get('drawingCanvas');if(!c)return;const ctx=c.getContext('2d');if(action==='undo-draw'){const last=canvasUndo.pop();if(!last)return;const img=new Image();img.onload=()=>{ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(img,0,0,c.width,c.height);window.__rudelCanvasImage=c.toDataURL('image/jpeg',.72);};img.src=last;}
if(action==='clear-draw'){ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);window.__rudelCanvasImage=null;canvasUndo=[];}
if(action==='save-draw'){const img=c.toDataURL('image/jpeg',.65);state.memories.unshift({id:uid(),title:'RUDEL Artwork',text:'Created in Together Studio (local)',image:img,date:Date.now(),visibility:'onlyMe'});persist();toast(tr('saveOnDevice'));}}
function openAudioDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('IndexedDB unsupported'));return;}const req=indexedDB.open('rudel-media-v1',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('voice'))db.createObjectStore('voice',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function mediaPut(record){const db=await openAudioDB();await new Promise((ok,fail)=>{const tx=db.transaction('voice','readwrite');tx.objectStore('voice').put(record);tx.oncomplete=ok;tx.onerror=()=>fail(tx.error);});db.close();}
async function mediaAll(){const db=await openAudioDB();const out=await new Promise((ok,fail)=>{const tx=db.transaction('voice','readonly');const req=tx.objectStore('voice').getAll();req.onsuccess=()=>ok(req.result);req.onerror=()=>fail(req.error);});db.close();return out;}
async function mediaDelete(id){const db=await openAudioDB();await new Promise((ok,fail)=>{const tx=db.transaction('voice','readwrite');tx.objectStore('voice').delete(id);tx.oncomplete=ok;tx.onerror=()=>fail(tx.error);});db.close();await loadAudioList();}
async function loadAudioList(){const dest=get('audio-list');if(!dest)return;audioUrls.forEach(x=>URL.revokeObjectURL(x));audioUrls=[];try{const all=(await mediaAll()).sort((a,b)=>b.date-a.date);if(!get('audio-list'))return;dest.innerHTML=all.length?all.map(rec=>{const url=URL.createObjectURL(rec.blob);audioUrls.push(url);return `<div class="list-row" style="flex-wrap:wrap"><div style="flex:1;min-width:135px"><strong>🎙 ${ts(rec.date)}</strong><div class="small-text">${(rec.blob.size/1024).toFixed(0)} KB · ${label('saveOnDevice')}</div></div><audio class="audio-bar" controls preload="none" src="${attr(url)}" aria-label="Recorded voice clip"></audio><a class="btn mini" href="${attr(url)}" download="rudel-voice-${rec.date}.webm">${label('download')}</a><button class="btn mini danger" data-action="delete-audio" data-id="${attr(rec.id)}">${label('delete')}</button></div>`;}).join(''):blank('🎙',tr('noItems'));}catch(e){dest.textContent='Audio storage unavailable in this browser.';}}
async function startRecording(){if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast(tr('permissionNeeded'));return;}try{audioStream=await navigator.mediaDevices.getUserMedia({audio:true});const parts=[];const opts=MediaRecorder.isTypeSupported('audio/webm')?{mimeType:'audio/webm'}:{};audioRecorder=new MediaRecorder(audioStream,opts);audioRecorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};audioRecorder.onstop=async()=>{const blob=new Blob(parts,{type:audioRecorder.mimeType||'audio/webm'});audioStream?.getTracks().forEach(t=>t.stop());audioStream=null;if(blob.size){try{await mediaPut({id:uid(),date:Date.now(),blob});toast(tr('saveOnDevice'));}catch(e){toast('Audio could not be saved.');}}audioRecorder=null;if(page==='sound'){render();}};audioRecorder.start();render();toast(tr('record'));}catch(e){audioStream?.getTracks().forEach(t=>t.stop());toast(tr('permissionNeeded'));}}
function stopRecording(){if(audioRecorder?.state==='recording')audioRecorder.stop();}
function handleClick(e){const button=e.target.closest('[data-action]');if(!button)return;const act=button.dataset.action,id=button.dataset.id;if(act==='visit'||act.startsWith('visit:')){if(page==='studio'&&get('drawingCanvas'))window.__rudelCanvasImage=get('drawingCanvas').toDataURL('image/jpeg',.72);route(button.dataset.to||act.split(':')[1]);return;}
if(act==='noop')return;
if(act==='drawer'){drawer=true;get('overlay').innerHTML=drawerMarkup();return;}
if(act==='close-drawer'){drawer=false;get('overlay').innerHTML='';return;}
if(act==='friend-chat'){selectedFriend=id;route('chat');return;}
if(act==='self-chat'){selectedFriend='self';route('chat');return;}
if(act==='remove-friend'){const f=state.friends.find(f=>f.id===id);if(f&&confirm(`${tr('delete')} ${f.name}?`)){removeFrom('friends',id);delete state.drafts[id];persist();}return;}
if(act==='delete-post'||act==='delete-circle'||act==='delete-memory'||act==='delete-note'||act==='delete-capsule'){if(!confirm(tr('delete')+'?'))return;removeFrom({ 'delete-post':'posts','delete-circle':'circles','delete-memory':'memories','delete-note':'notes','delete-capsule':'capsules'}[act],id);return;}
if(act==='save-post-draft'){state.postDraft=(get('postText')?.value||'').slice(0,2000);persist();toast(tr('saveDraft'));return;}
if(act==='like-post'){const p=state.posts.find(x=>x.id===id);if(p){p.liked=!p.liked;p.likes=p.liked?1:0;persist();render();}return;}
if(act==='game-select'){selectedGame=button.dataset.game==='snake'?'snake':'ttt';render();return;}
if(act==='ttt-move'){tttMove(Number(button.dataset.index));return;}
if(act==='reset-ttt'){resetTtt();return;}
if(act==='roll-dice'){rollDice();return;}
if(act==='reset-snake'){resetSnake();return;}
if(act==='restart-story'){if(confirm(tr('replayStory')+'?')){state.story.chapter=0;state.story.choices={};state.story.clues=[];persist();render();}return;}
if(act==='story-choice'){storyChoice(Number(button.dataset.index));return;}
if(act==='chapter-prev'){setChapter(state.story.chapter-1);return;}
if(act==='chapter-next'){setChapter(state.story.chapter+1);return;}
if(act==='speak-story'){speak(str(D.story[state.story.chapter].body)+(state.story.choices[7]!==undefined&&state.story.chapter===7?' '+str(D.endings[endingIndex()]):''));return;}
if(act==='speak-ui'){speak([tr('welcome'),tr('tagline'),tr('settings'),tr('language')].join('. '));return;}
if(act==='stop-speech'){window.speechSynthesis?.cancel();return;}
if(act==='cache-story'){cacheOffline();return;}
if(act==='set-color'){canvasColor=button.dataset.color;document.querySelectorAll('.swatch').forEach(x=>x.classList.toggle('selected',x.dataset.color===canvasColor));return;}
if(['undo-draw','clear-draw','save-draw'].includes(act)){canvasImageAction(act);return;}
if(act==='play-chime'){playOriginalChime();return;}
if(act==='start-record'){startRecording();return;}
if(act==='stop-record'){stopRecording();return;}
if(act==='delete-audio'){if(confirm(tr('delete')+'?'))mediaDelete(id);return;}
if(act==='export-data'){exportData();return;}
if(act==='clear-data'){clearData();return;}
}
function onSearch(e){const el=e.target;if(!el.matches('[data-search]'))return;const pos=el.selectionStart;query=el.value;const section=el.dataset.search;const elId=section==='friends'?'friends':'feed';const main=get('main');main.innerHTML=elId==='friends'?renderFriends():renderFeed();const next=main.querySelector('[data-search]');if(next){next.focus();next.setSelectionRange(pos,pos);}}
function init(){load();extraInit();const hash=location.hash.slice(1);page=PAGES.includes(hash)?hash:'home';render();toggleIntro();document.addEventListener('click',handleClick);document.addEventListener('submit',handleForm);document.addEventListener('change',changeSetting);document.addEventListener('input',onSearch);window.addEventListener('hashchange',()=>{const path=location.hash.slice(1);if(PAGES.includes(path)&&path!==page){page=path;render();}});setInterval(tick,1000);if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));}}
// RUDEL Universe 1.0: functional local-first modules, no simulated remote users.
const EXTRA_PAGES=['arcade','quests','journal','events','polls','creator','photolab','gallery','soundscapes','achievements','backup','roadmap'];
const EXTRA_ICONS={arcade:'🕹️',quests:'⚡',journal:'🌙',events:'📅',polls:'📊',creator:'✨',photolab:'📸',gallery:'🖼️',soundscapes:'🎧',achievements:'🏆',backup:'🔐',roadmap:'🧭'};
const EXTRA_NAMES={
 en:['Arcade Plus','Creative Quests','Mood Journal','Events & Plans','Circle Polls','Poster Creator','Photo Lab','Media Gallery','Soundscapes','Achievements','Backup & Restore','Product Roadmap'],
 hi:['आर्केड प्लस','रचनात्मक मिशन','मूड डायरी','कार्यक्रम और योजनाएँ','समूह मतदान','पोस्टर क्रिएटर','फ़ोटो लैब','मीडिया गैलरी','ध्वनि संसार','उपलब्धियाँ','बैकअप और वापसी','उत्पाद योजना'],
 mr:['आर्केड प्लस','सर्जनशील मोहिमा','मूड डायरी','कार्यक्रम व योजना','गट मतदान','पोस्टर तयार करा','फोटो लॅब','मीडिया गॅलरी','ध्वनीविश्व','कामगिरी','बॅकअप आणि पुनर्स्थापना','विकास आराखडा'],
 bn:['আর্কেড প্লাস','সৃজনশীল মিশন','মুড ডায়েরি','ইভেন্ট ও পরিকল্পনা','গ্রুপ ভোট','পোস্টার তৈরি','ফটো ল্যাব','মিডিয়া গ্যালারি','সাউন্ডস্কেপ','অর্জন','ব্যাকআপ ও ফিরিয়ে আনা','প্রোডাক্ট রোডম্যাপ'],
 ta:['ஆர்கேட் பிளஸ்','படைப்புச் சவால்கள்','மனநிலை நாட்குறிப்பு','நிகழ்வுகள்','குழு வாக்கெடுப்பு','சுவரொட்டி உருவாக்கி','புகைப்பட ஆய்வகம்','ஊடகக் காட்சியகம்','ஒலி உலகம்','சாதனைகள்','காப்பு மற்றும் மீட்பு','தயாரிப்பு திட்டம்']};
function exName(k){const i=EXTRA_PAGES.indexOf(k);return EXTRA_NAMES[state.lang]?.[i]||EXTRA_NAMES.en[i]||k;}
function exHead(k,sub=''){return `<div class="eyebrow">✦ RUDEL UNIVERSE</div><h1 class="title">${esc(exName(k))}</h1>${sub?`<p class="lead">${esc(sub)}</p>`:''}`;}
const exNote=(s)=>`<div class="micro-note"><span class="micro-dot"></span>${esc(s||'Saved privately on this device • Not synced to other users')}</div>`;
function exEnsure(){state.journal=Array.isArray(state.journal)?state.journal:[];state.events=Array.isArray(state.events)?state.events:[];state.polls=Array.isArray(state.polls)?state.polls:[];state.questDone=state.questDone||{};state.score=state.score||{rps:0,memory:0,twenty48:0,reaction:0};}
const QUESTS=[['✨','Create your first memory','memories'],['👋','Add a friend star','friends'],['📖','Explore a story chapter','stories'],['🖌️','Design an original artwork','studio'],['🌙','Write a mood journal entry','journal'],['🎮','Play the arcade','arcade'],['🪐','Personalize your RUDEL profile','profile'],['🎁','Create a surprise capsule','capsules']];
function exQuestCount(){return QUESTS.filter((q,i)=>state.questDone[i]).length;}
function renderQuests(){exEnsure();return `${exHead('quests','Create at your own pace. Every badge is cosmetic; there are no streak penalties.')}
<section class="achievement-hero"><span class="badge">RUDEL QUESTS</span><h2>${exQuestCount()} / ${QUESTS.length} unlocked</h2><div class="progress"><span style="width:${100*exQuestCount()/QUESTS.length}%"></span></div><p>Find your own constellation, one creative moment at a time.</p></section><div class="stack">${QUESTS.map((q,i)=>`<div class="quest-row"><span class="quest-emblem">${q[0]}</span><div style="flex:1"><strong>${esc(q[1])}</strong><div class="small-text">Cosmetic RUDEL star · ${state.questDone[i]?'Completed':'Your choice'}</div></div><button class="btn mini ${state.questDone[i]?'':'primary'}" data-action="quest-toggle" data-index="${i}">${state.questDone[i]?'✓ Done':'Mark done'}</button><button class="btn mini" data-action="visit" data-to="${q[2]}">Open</button></div>`).join('')}</div>${exNote()}`;}
const MOODS=[['🌟','Amazing'],['🙂','Good'],['😐','Okay'],['🌧️','Low'],['🌱','Growing']];
function renderJournal(){exEnsure();return `${exHead('journal','Your private space for thoughts, colors and daily moments.')}
<section class="card"><form data-exform="journal"><h3>How is your universe today?</h3><div class="mood-picker">${MOODS.map((x,i)=>`<label class="mood-choice"><input type="radio" name="mood" value="${i}" ${i===2?'checked':''}><span>${x[0]}</span><small>${x[1]}</small></label>`).join('')}</div>${area('journalText','A thought worth remembering','Your words stay on this device...')}<button class="btn primary" type="submit">✦ Save private entry</button></form></section><div class="section-head"><h2>My journal · ${state.journal.length}</h2></div><div class="stack">${state.journal.length?state.journal.map(j=>`<article class="card flat journal-entry"><div class="flex-between"><strong>${MOODS[j.mood]?.[0]||'🌙'} ${MOODS[j.mood]?.[1]||'Reflection'}</strong><button class="btn mini danger" data-action="ex-delete" data-collection="journal" data-id="${attr(j.id)}">Delete</button></div><p>${esc(j.text)}</p><small class="muted">${ts(j.date)}</small></article>`).join(''):blank('🌙','Start your journal with a private thought.')}</div>${exNote()}`;}
function renderEvents(){exEnsure();return `${exHead('events','Plan a birthday, friendship hangout or circle moment. Events are local drafts, not sent to friends.')}
<section class="card flat"><form data-exform="event">${formField('eventTitle','Event name','','Birthday surprise','text',true)}${formField('eventWhen','Date and time','','','datetime-local',true)}${area('eventDetails','Plan / notes','What do you want to remember?')}<button class="btn primary" type="submit">+ Add event</button></form></section><div class="section-head"><h2>Upcoming plans</h2></div><div class="stack">${state.events.length?state.events.slice().sort((a,b)=>a.when-b.when).map(ev=>`<div class="card flat"><div class="flex-between"><strong>📅 ${esc(ev.title)}</strong><button class="btn mini danger" data-action="ex-delete" data-collection="events" data-id="${attr(ev.id)}">✕</button></div><div class="eyebrow">${ts(ev.when)}</div><p>${esc(ev.details)}</p><button class="btn mini" data-action="event-ics" data-id="${attr(ev.id)}">⬇ Calendar file (.ics)</button></div>`).join(''):blank('📅','No planned events yet.')}</div>${exNote('Your event stays on this device until you export a calendar file.')}`;}
function renderPolls(){exEnsure();return `${exHead('polls','Build a private poll and collect votes locally on one device.')}
<section class="card"><form data-exform="poll">${formField('pollQuestion','Question','','Which game tonight?','text',true)}${area('pollOptions','Options (one per line)','Tic Tac Toe\nSnakes & Ladders\n2048')}<button class="btn primary" type="submit">+ Create poll</button></form></section><div class="stack" style="margin-top:16px">${state.polls.length?state.polls.map(p=>{const total=p.votes.reduce((a,b)=>a+b,0);return `<section class="card flat"><div class="flex-between"><h3>${esc(p.question)}</h3><button class="btn mini danger" data-action="ex-delete" data-collection="polls" data-id="${attr(p.id)}">✕</button></div>${p.options.map((o,i)=>`<button class="poll-option" data-action="poll-vote" data-id="${attr(p.id)}" data-index="${i}"><div class="flex-between"><span>${esc(o)}</span><strong>${p.votes[i]} · ${total?Math.round(p.votes[i]/total*100):0}%</strong></div><span class="poll-bar" style="width:${total?p.votes[i]/total*100:0}%"></span></button>`).join('')}<p class="small-text">${total} votes · local demo, not a public poll</p></section>`}).join(''):blank('📊','Your first poll starts here.')}</div>${exNote('Votes are stored only on this device, not collected online.')}`;}
let arcadeGame='memory',memoryBoard=[],memoryOpen=[],memoryMatched=[],memoryTries=0,game2048=[],game2048Score=0,reactionStart=0,reactionMode='ready',rpsPick=-1;
function freshMemory(){const v=['🌌','🚀','🪐','🌠','⭐','☄️','🌙','🌈'];memoryBoard=[...v,...v].map((a,i)=>({a,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.a);memoryOpen=[];memoryMatched=[];memoryTries=0;}
function spawn2048(){const spots=game2048.flatMap((n,i)=>n===0?[i]:[]);if(spots.length){const pos=spots[Math.floor(Math.random()*spots.length)];game2048[pos]=Math.random()<.9?2:4;}}
function fresh2048(){game2048=Array(16).fill(0);game2048Score=0;spawn2048();spawn2048();}
function move2048(dir){if(game2048.length!==16)fresh2048();const original=game2048.join(',');const old=[...game2048];for(let line=0;line<4;line++){
let idx=[];for(let n=0;n<4;n++)idx.push(dir==='left'?line*4+n:dir==='right'?line*4+(3-n):dir==='up'?n*4+line:(3-n)*4+line);
let values=idx.map(i=>old[i]).filter(Boolean),merged=[];for(let p=0;p<values.length;p++){if(values[p]===values[p+1]){merged.push(values[p]*2);game2048Score+=values[p]*2;p++;}else merged.push(values[p]);}while(merged.length<4)merged.push(0);idx.forEach((i,k)=>game2048[i]=merged[k]);}
if(original!==game2048.join(',')){spawn2048();state.score.twenty48=Math.max(state.score.twenty48||0,game2048Score);persist();}render();}
function renderArcade(){exEnsure();if(!memoryBoard.length)freshMemory();if(!game2048.length)fresh2048();const tabs=[['memory','🃏 Memory Match'],['2048','🔢 2048'],['rps','✊ Rock Paper Scissors'],['reaction','⚡ Reaction Test']];let board='';
if(arcadeGame==='memory')board=`<div class="flex-between"><div>Pairs: <strong>${memoryMatched.length/2}/8</strong> · Moves: ${memoryTries}</div><button class="btn mini" data-action="arcade-restart">↻ New game</button></div><div class="memory-grid">${memoryBoard.map((v,i)=>`<button class="memory-tile ${memoryOpen.includes(i)||memoryMatched.includes(i)?'revealed':''}" data-action="memory-flip" data-index="${i}" ${memoryOpen.includes(i)||memoryMatched.includes(i)?'disabled':''}>${memoryOpen.includes(i)||memoryMatched.includes(i)?v:'✦'}</button>`).join('')}</div>${memoryMatched.length===16?`<div class="note successnote">✨ Excellent! Completed in ${memoryTries} moves.</div>`:''}`;
if(arcadeGame==='2048')board=`<div class="flex-between"><strong>Score: ${game2048Score}</strong><span>Best: ${state.score.twenty48||0}</span></div><div class="twenty-board">${game2048.map(n=>`<div class="twenty-tile v${n}">${n||''}</div>`).join('')}</div><div class="direction-pad"><button class="btn" data-action="2048-move" data-direction="left">←</button><button class="btn" data-action="2048-move" data-direction="up">↑</button><button class="btn" data-action="2048-move" data-direction="down">↓</button><button class="btn" data-action="2048-move" data-direction="right">→</button></div><button class="btn mini" data-action="arcade-restart">↻ New grid</button><p class="small-text">Combine equal tiles. Arrow keys also work.</p>`;
if(arcadeGame==='rps')board=`<div class="rps-hero">${rpsPick>=0?['🪨','📄','✂️'][rpsPick]:'✊'} <span>VS</span> 🤖</div><h3 style="text-align:center">Choose your move</h3><div class="rps-picks">${['🪨','📄','✂️'].map((v,i)=>`<button class="rps-btn" data-action="rps-play" data-index="${i}">${v}<small>${['Rock','Paper','Scissors'][i]}</small></button>`).join('')}</div><div id="rps-result" class="small-text" style="text-align:center;margin-top:12px">Your wins: ${state.score.rps||0}</div>`;
if(arcadeGame==='reaction')board=`<div class="reaction-pad ${reactionMode}" data-action="reaction-hit"><strong>${reactionMode==='go'?'TAP!':reactionMode==='wait'?'WAIT…':reactionMode==='done'?'PLAY AGAIN':'TAP TO START'}</strong><small>${reactionMode==='ready'?'How fast can you respond?':'Best: '+(state.score.reaction||'–')+' ms'}</small></div><p class="small-text">Wait for the pad to turn green, then tap it. False starts reset.</p>`;
return `${exHead('arcade','Four additional real solo games. Rudra · RUDEL Games.')}
<div class="pill-group space-bottom">${tabs.map(x=>`<button class="pill ${arcadeGame===x[0]?'active':''}" data-action="arcade-select" data-game="${x[0]}">${x[1]}</button>`).join('')}</div><section class="card flat">${board}</section><button class="btn full" style="margin-top:14px" data-action="visit" data-to="games">🎮 Tic Tac Toe + Snakes & Ladders</button>${exNote('Games are fully local. Online matches need a real backend.')}`;}
function renderAchievements(){exEnsure();const earned=[state.friends.length>0,state.posts.length>0,(state.memories.length>0),state.story.clues.length>0,state.events.length>0,state.journal.length>0,exQuestCount()>=4,(state.score.rps||0)>0,(state.score.memory||0)>0];const medals=['Friendship Spark','Creator Light','Memory Keeper','Story Explorer','Event Planner','Mood Navigator','Quest Adventurer','Rock Champion','Memory Master'];const faces=['🪐','✍️','🌟','📚','📅','🌙','⚡','✊','🃏'];return `${exHead('achievements','Earn original, cosmetic badges by exploring your own universe.')}
<section class="achievement-hero"><div class="mega-emoji">🏆</div><h2>${earned.filter(Boolean).length} / ${earned.length} Achievements</h2><div class="progress"><span style="width:${earned.filter(Boolean).length/earned.length*100}%"></span></div></section><div class="grid badge-grid">${medals.map((v,i)=>`<div class="card badge-card ${earned[i]?'':'badge-locked'}"><div>${faces[i]}</div><strong>${v}</strong><small>${earned[i]?'Unlocked':'Not yet unlocked'}</small></div>`).join('')}</div>`;}
function renderGallery(){const media=[...state.memories.filter(m=>m.image).map(m=>({...m,kind:'Memory'})),...state.posts.filter(p=>p.image).map(p=>({...p,title:(p.text||'Post').slice(0,30),kind:'Post'}))];return `${exHead('gallery','Your private on-device photo constellation.')}
<div class="grid media-grid">${media.length?media.map(m=>`<div class="gallery-item"><img src="${attr(m.image)}" alt="${attr(m.title||m.kind)}" loading="lazy"><div><strong>${esc(m.title||m.kind)}</strong><small>${esc(m.kind)} · ${ts(m.date)}</small></div></div>`).join(''):blank('🖼️','No pictures yet. Add photos in Memories or Posts.')}</div>${exNote()}`;}
let posterTheme='aurora',posterText='Our universe, our story.',posterSubtitle='RUDEL · Friendship Forever',posterReady=false;
const POSTER_THEMES={aurora:['#0d1234','#8155f4','#77ded4'],royal:['#221025','#a06de5','#f3cb85'],vibrant:['#100d3c','#ed72be','#87b9ff']};
function paintPoster(){const c=get('posterCanvas');if(!c)return;const x=c.getContext('2d'),w=c.width,h=c.height,cl=POSTER_THEMES[posterTheme];x.fillStyle=cl[0];x.fillRect(0,0,w,h);const g=x.createRadialGradient(w*.5,h*.4,20,w*.5,h*.4,w*.8);g.addColorStop(0,cl[1]+'77');g.addColorStop(1,'#00000000');x.fillStyle=g;x.fillRect(0,0,w,h);x.strokeStyle=cl[2];x.lineWidth=4;x.save();x.translate(w/2,h*.42);x.rotate(-.27);x.beginPath();x.ellipse(0,0,345,130,0,0,Math.PI*2);x.stroke();x.rotate(.55);x.beginPath();x.ellipse(0,0,275,185,0,0,Math.PI*2);x.stroke();x.restore();x.beginPath();x.arc(w/2,h*.42,95,0,Math.PI*2);x.fillStyle=cl[1];x.shadowColor=cl[1];x.shadowBlur=90;x.fill();x.shadowBlur=0;x.font='bold 95px sans-serif';x.textAlign='center';x.fillStyle='#fff';x.fillText('✦',w/2,h*.452);for(let i=0;i<38;i++){const sx=(i*73+17)%w,sy=(i*193+47)%h;x.fillStyle=i%5?'#ffffff88':cl[2];x.beginPath();x.arc(sx,sy,1+(i%3),0,Math.PI*2);x.fill();}
function wrapText(text,y,font,maxWidth,dy){x.font=font;const words=text.split(/\s+/),lines=[];let line='';for(const word of words){if(x.measureText((line+' '+word).trim()).width>maxWidth&&line){lines.push(line);line=word;}else line=(line+' '+word).trim();}lines.push(line);lines.slice(0,5).forEach((l,i)=>x.fillText(l,w/2,y+i*dy));}
x.fillStyle='#ffffff';wrapText(posterText.slice(0,130),h*.68,'bold 58px sans-serif',w-110,75);x.fillStyle=cl[2];wrapText(posterSubtitle.slice(0,90),h*.85,'28px sans-serif',w-110,42);x.fillStyle='#ffffffbb';x.font='bold 30px sans-serif';x.fillText('RUDEL  ·  YOUR UNIVERSE',w/2,h-60);posterReady=true;}
function renderCreator(){return `${exHead('creator','Craft an original cinematic poster. Download it or save it into your Memory Vault.')}
<section class="card flat"><div class="field"><label>Poster title</label><input id="posterText" maxlength="130" value="${attr(posterText)}"></div><div class="field"><label>Subtitle</label><input id="posterSubtitle" maxlength="90" value="${attr(posterSubtitle)}"></div><div class="field"><label>Universe theme</label><select id="posterTheme"><option value="aurora" ${posterTheme==='aurora'?'selected':''}>Cosmic Aurora</option><option value="royal" ${posterTheme==='royal'?'selected':''}>Royal Nebula</option><option value="vibrant" ${posterTheme==='vibrant'?'selected':''}>Vibrant Galaxy</option></select></div><canvas id="posterCanvas" width="750" height="1000" class="poster-canvas" aria-label="Generated poster"></canvas><div class="flex wrap" style="margin-top:14px"><button class="btn primary" data-action="poster-generate">✦ Render poster</button><button class="btn" data-action="poster-save">♡ Save to Vault</button><button class="btn" data-action="poster-download">⬇ Download PNG</button></div></section>${exNote('All artwork is generated locally, without external music or copyrighted media.')}`;}
let photoImg=null,photoRotate=0,photoLum=100,photoSat=100;
function paintPhoto(){const c=get('photoCanvas');if(!c||!photoImg)return;const w=photoImg.width,h=photoImg.height,turn=((photoRotate%360)+360)%360,cross=turn===90||turn===270;c.width=cross?h:w;c.height=cross?w:h;const x=c.getContext('2d');x.fillStyle='#101626';x.fillRect(0,0,c.width,c.height);x.save();x.translate(c.width/2,c.height/2);x.rotate(photoRotate*Math.PI/180);x.filter=`brightness(${photoLum}%) saturate(${photoSat}%)`;x.drawImage(photoImg,-w/2,-h/2,w,h);x.restore();}
function renderPhotoLab(){return `${exHead('photolab','Edit photos locally with adjustable light, color and rotation. Export a true edited image.')}
<section class="card"><div class="field"><label for="photoInput">Choose photo / use your camera</label><input type="file" id="photoInput" accept="image/*" capture="environment"></div>${photoImg?`<div class="photo-preview"><canvas id="photoCanvas" aria-label="Editable photograph"></canvas></div><div class="field"><label>Brightness <output>${photoLum}%</output></label><input type="range" id="photoLum" min="30" max="180" value="${photoLum}"></div><div class="field"><label>Color intensity <output>${photoSat}%</output></label><input type="range" id="photoSat" min="0" max="200" value="${photoSat}"></div><div class="flex wrap"><button class="btn" data-action="photo-rotate">⟳ Rotate</button><button class="btn" data-action="photo-reset">Reset</button><button class="btn primary" data-action="photo-export">⬇ Save edited photo</button></div>`:`<div class="photo-empty">📸<h3>Start with your photo</h3><p class="muted">Pick or capture an image to open the Photo Lab.</p></div>`}</section>${exNote('No cloud processing, no face manipulation. Original image stays on your device.')}`;}
let soundNodes=null;
function soundOff(){if(soundNodes){try{soundNodes.oscs.forEach(o=>o.stop());soundNodes.ctx.close();}catch(e){}soundNodes=null;}}
function ambient(name){soundOff();if(!state.sound||state.quietMode){toast('Turn on sound in Settings to play ambience.');return;}const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('Audio unavailable.');return;}const ctx=new AC(),g=ctx.createGain();g.gain.value=.018;g.connect(ctx.destination);const patterns={nebula:[110,164.81,220],aurora:[146.83,196,293.66],starlight:[174.61,261.63,349.23]};const oscs=patterns[name].map((f,i)=>{const o=ctx.createOscillator();o.type=i===0?'sine':'triangle';o.frequency.value=f;o.connect(g);o.start();return o;});soundNodes={ctx,oscs};}
function renderSoundscapes(){return `${exHead('soundscapes','Original ambient synthesis. Nothing is downloaded or played from copyrighted music sources.')}
<section class="sound-hero"><div style="font-size:3.6rem">🎧</div><h2>Choose your atmosphere</h2><p>Soft generative tones for exploring RUDEL.</p></section><div class="grid">${[['nebula','🌌 Nebula Drift'],['aurora','🪐 Aurora Glow'],['starlight','✨ Starlight']].map(q=>`<button class="sound-card" data-action="ambient-start" data-sound="${q[0]}"><span>${q[1].split(' ')[0]}</span><strong>${q[1].split(' ').slice(1).join(' ')}</strong><small>Tap to listen</small></button>`).join('')}</div><button class="btn full" style="margin-top:16px" data-action="ambient-stop">■ Stop sound</button>${exNote('Respect quiet mode. Ambient playback is a local audio feature.')}`;}
function renderBackup(){return `${exHead('backup','Take your memories with you. Export or restore your local data safely.')}
<div class="card flat"><h3>🔐 Export your private collection</h3><p class="muted">Download profile, posts, memories, local events, journals, polls, story choices, quests and settings as JSON. Recorded voice clips are stored separately.</p><button class="btn primary" data-action="export-data">⬇ Export RUDEL data</button></div><div class="card flat" style="margin-top:14px"><h3>📥 Restore from file</h3><p class="muted">Only import your own RUDEL JSON backup. Existing local data will be replaced after confirmation.</p><input type="file" accept="application/json,.json" id="rudelImport"><button class="btn" data-action="backup-import" style="margin-top:12px">↥ Import backup</button></div><div class="card flat" style="margin-top:14px"><h3>⚠ Delete local data</h3><p class="muted">Permanently erase data stored in this app on this device.</p><button class="btn danger" data-action="clear-data">Clear this device</button></div>`;}
const roadmapData=[['LIVE ON DEVICE','Living Orbit, three original themes, multi-language UI, 2 classic games, 4 mini-games, 8-chapter interactive story, journals, memories, posts, creative art, privacy controls, story narration where supported'],['LOCAL ONLY','Friend stars, circles, events, polls, scheduled capsules (when app is opened), private notes, photo creator, on-device backups, creative quests, scoreboards'],['REQUIRES SERVER','Actual user accounts and verified email/Google login, multi-device sync, remote chats, multiplayer matches, public communities, push delivery, online report review and human moderation'],['FUTURE CREATIVE PRODUCTION','20 fully-written stories, advanced video editing and render, real-time together studio, licensed music embeds, large media vault, tournaments, APK parity for native camera and recorder']];
function renderRoadmap(){return `${exHead('roadmap','Transparent features. No false online indicators, fake users or pretend matches.')}${roadmapData.map(([k,s])=>`<div class="card flat" style="margin-bottom:13px"><div class="eyebrow">${k}</div><p>${esc(s)}</p></div>`).join('')}`;}
function downloadBlob(b,name){const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),12000);}
function extraClick(e){const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,ind=Number(b.dataset.index);exEnsure();if(a==='quest-toggle'){state.questDone[ind]=!state.questDone[ind];persist();render();return;}
if(a==='ex-delete'){const k=b.dataset.collection;if(!['journal','events','polls'].includes(k))return;if(confirm('Delete this private entry?')){state[k]=state[k].filter(v=>v.id!==id);persist();render();}return;}
if(a==='event-ics'){const ev=state.events.find(x=>x.id===id);if(!ev)return;const icsTime=t=>new Date(t).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=v=>String(v).replace(/[\\;,\n]/g,' ');const txt=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//RUDEL//Local Planner//EN','BEGIN:VEVENT','UID:'+ev.id+'@rudel.local','DTSTAMP:'+icsTime(Date.now()),'DTSTART:'+icsTime(ev.when),'DTEND:'+icsTime(ev.when+3600000),'SUMMARY:'+clean(ev.title),'DESCRIPTION:'+clean(ev.details),'END:VEVENT','END:VCALENDAR'].join('\r\n');downloadBlob(new Blob([txt],{type:'text/calendar'}),'RUDEL-event.ics');return;}
if(a==='poll-vote'){const p=state.polls.find(x=>x.id===id);if(!p||!Number.isInteger(ind)||ind<0||ind>=p.votes.length)return;p.votes[ind]++;persist();render();return;}
if(a==='arcade-select'){arcadeGame=b.dataset.game;reactionMode='ready';render();return;}
if(a==='arcade-restart'){if(arcadeGame==='memory')freshMemory();if(arcadeGame==='2048')fresh2048();reactionMode='ready';render();return;}
if(a==='memory-flip'){if(memoryOpen.length>=2||memoryMatched.includes(ind)||memoryOpen.includes(ind)||!memoryBoard[ind])return;memoryOpen.push(ind);if(memoryOpen.length===2){memoryTries++;const [v,w]=memoryOpen;if(memoryBoard[v]===memoryBoard[w]){memoryMatched.push(v,w);memoryOpen=[];if(memoryMatched.length===16){state.score.memory=(state.score.memory||0)+1;persist();}}else{setTimeout(()=>{memoryOpen=[];if(page==='arcade'&&arcadeGame==='memory')render();},650);}}render();return;}
if(a==='2048-move'){move2048(b.dataset.direction);return;}
if(a==='rps-play'){rpsPick=ind;const bot=Math.floor(Math.random()*3),result=ind===bot?'Tie':(ind-bot+3)%3===1?'You win!':'Computer wins!';if(result==='You win!'){state.score.rps=(state.score.rps||0)+1;persist();}render();const out=get('rps-result');if(out)out.textContent=`You: ${['Rock','Paper','Scissors'][ind]} · Computer: ${['Rock','Paper','Scissors'][bot]} — ${result} · Wins: ${state.score.rps}`;return;}
if(a==='reaction-hit'){if(reactionMode==='ready'||reactionMode==='done'){reactionMode='wait';reactionStart=0;render();setTimeout(()=>{if(reactionMode==='wait'){reactionMode='go';reactionStart=performance.now();if(page==='arcade'&&arcadeGame==='reaction')render();}},1200+Math.random()*2200);}else if(reactionMode==='wait'){reactionMode='ready';toast('Too early! Try again.');render();}else if(reactionMode==='go'){const v=Math.round(performance.now()-reactionStart);reactionMode='done';state.score.reaction=state.score.reaction?Math.min(v,state.score.reaction):v;persist();render();toast(`${v} ms reaction · Best ${state.score.reaction} ms`);}return;}
if(a==='poster-generate'){posterText=get('posterText')?.value||posterText;posterSubtitle=get('posterSubtitle')?.value||posterSubtitle;posterTheme=get('posterTheme')?.value||posterTheme;paintPoster();toast('Your poster is ready.');return;}
if(a==='poster-download'||a==='poster-save'){const c=get('posterCanvas');if(!c)return;if(!posterReady)paintPoster();if(a==='poster-download')c.toBlob(b=>b&&downloadBlob(b,'RUDEL-Original-Poster.png'),'image/png');else{state.memories.unshift({id:uid(),title:posterText.slice(0,100)||'Original poster',text:'Created in RUDEL Poster Studio',image:c.toDataURL('image/jpeg',.8),date:Date.now(),visibility:'onlyMe'});if(persist())toast('Poster saved in Memories.');}return;}
if(a==='photo-rotate'){photoRotate=(photoRotate+90)%360;paintPhoto();return;}
if(a==='photo-reset'){photoRotate=0;photoLum=100;photoSat=100;render();return;}
if(a==='photo-export'){if(!photoImg)return;get('photoCanvas')?.toBlob(b=>b&&downloadBlob(b,'RUDEL-edited-photo.png'),'image/png');return;}
if(a==='ambient-start'){ambient(b.dataset.sound);toast('Original RUDEL ambience playing.');return;}
if(a==='ambient-stop'){soundOff();toast('Sound stopped.');return;}
if(a==='backup-import'){const file=get('rudelImport')?.files?.[0];if(!file){toast('Choose a backup JSON file first.');return;}if(file.size>5e6){toast('Backup is too large to import here.');return;}file.text().then(s=>{let item;try{item=JSON.parse(s);}catch{toast('Invalid JSON file.');return;}if(item?.app!=='RUDEL'||!item?.data||typeof item.data!=='object'||Array.isArray(item.data)||!Array.isArray(item.data.posts)||!Array.isArray(item.data.friends)){toast('Not a valid RUDEL backup.');return;}if(!confirm('Replace the RUDEL data on this device with this backup?'))return;try{localStorage.setItem('rudel-v1',JSON.stringify({...DEFAULT,...item.data}));load();exEnsure();render();toast('Backup restored.');}catch{toast('Unable to restore. Storage might be full.');}});return;}}
function extraSubmit(e){const f=e.target.closest('form[data-exform]');if(!f)return;e.preventDefault();exEnsure();const fd=new FormData(f),kind=f.dataset.exform;if(kind==='journal'){const val=String(fd.get('journalText')||'').trim();if(!val){toast('Write a thought first.');return;}state.journal.unshift({id:uid(),mood:Math.max(0,Math.min(4,Number(fd.get('mood'))||0)),text:val.slice(0,2000),date:Date.now()});}
if(kind==='event'){const title=String(fd.get('eventTitle')||'').trim(),when=Date.parse(fd.get('eventWhen'));if(!title||!Number.isFinite(when)){toast('Enter an event and date.');return;}state.events.unshift({id:uid(),title:title.slice(0,100),when,details:String(fd.get('eventDetails')||'').slice(0,2000),date:Date.now()});}
if(kind==='poll'){const question=String(fd.get('pollQuestion')||'').trim(),options=String(fd.get('pollOptions')||'').split(/\r?\n/).map(v=>v.trim()).filter(Boolean).slice(0,8);if(!question||options.length<2){toast('Add a question and at least two choices.');return;}state.polls.unshift({id:uid(),question:question.slice(0,180),options,votes:options.map(()=>0),date:Date.now()});}
persist();render();toast('Saved privately on this device.');}
